import os
from pathlib import Path

import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file among `names`.

    Each name is a path relative to the directory `notes` in the current
    working directory; names may include subdirectories ("sub/b.txt").
    Names are untrusted: any name that would reach a file outside `notes`
    (via "..", absolute paths, symlinks, etc.) counts as unreadable.
    Missing, unreadable, non-file, or invalid names (e.g. containing NUL)
    are skipped. Returns "" if no name is readable.
    """
    try:
        base = Path("notes").resolve(strict=True)
    except (OSError, RuntimeError, ValueError):
        return ""
    for name in names:
        if "\x00" in name:
            continue
        try:
            target = (base / name).resolve(strict=True)
            if not target.is_relative_to(base):
                continue
            if not target.is_file():
                continue
            return target.read_text(encoding="utf-8")
        except (OSError, RuntimeError, ValueError):
            continue
    return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello")
    (notes / "sub" / "b.txt").write_text("bee")
    (notes / "empty.txt").write_text("")
    (tmp_path / "secret.txt").write_text("SECRET")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("EVIL")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_basic_read(root: Path) -> None:
    assert first_readable(["a.txt"]) == "hello"


def test_empty_list(root: Path) -> None:
    assert first_readable([]) == ""


def test_none_readable(root: Path) -> None:
    assert first_readable(["nope.txt", "also/missing.txt"]) == ""


def test_skips_missing_returns_first_readable(root: Path) -> None:
    assert first_readable(["nope.txt", "a.txt", "sub/b.txt"]) == "hello"


def test_subdirectory(root: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "bee"


def test_empty_file_counts_as_readable(root: Path) -> None:
    assert first_readable(["empty.txt", "a.txt"]) == ""


def test_directory_name_is_skipped(root: Path) -> None:
    assert first_readable(["sub", "a.txt"]) == "hello"
    assert first_readable(["sub"]) == ""


def test_empty_and_dot_names_skipped(root: Path) -> None:
    assert first_readable(["", ".", "a.txt"]) == "hello"
    assert first_readable(["", "."]) == ""


def test_dotdot_inside_notes_is_fine(root: Path) -> None:
    assert first_readable(["sub/../a.txt"]) == "hello"


def test_traversal_blocked(root: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["../secret.txt", "a.txt"]) == "hello"


def test_nested_traversal_blocked(root: Path) -> None:
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt", "sub/b.txt"]) == "bee"


def test_deep_traversal_blocked(root: Path) -> None:
    assert first_readable(["../../../../../../../../etc/passwd"]) == ""


def test_sibling_prefix_directory_blocked(root: Path) -> None:
    assert first_readable(["../notes_evil/x.txt"]) == ""


def test_absolute_path_blocked(root: Path) -> None:
    secret = str(root / "secret.txt")
    assert first_readable([secret]) == ""
    assert first_readable([secret, "a.txt"]) == "hello"


def test_absolute_path_to_file_in_notes_not_leaking_outside(root: Path) -> None:
    assert first_readable([str(root / "notes_evil" / "x.txt")]) == ""


def test_nul_byte_skipped(root: Path) -> None:
    assert first_readable(["a\x00.txt", "a.txt"]) == "hello"
    assert first_readable(["a.txt\x00../../secret.txt"]) == ""


def test_symlink_file_escape_blocked(root: Path) -> None:
    link = root / "notes" / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "hello"


def test_symlink_dir_escape_blocked(root: Path) -> None:
    link = root / "notes" / "linkdir"
    try:
        link.symlink_to(root, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["linkdir/secret.txt"]) == ""


def test_symlink_inside_notes_allowed(root: Path) -> None:
    link = root / "notes" / "alias.txt"
    try:
        link.symlink_to(root / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert first_readable(["alias.txt"]) == "hello"


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits not enforced",
)
def test_permission_denied_skipped(root: Path) -> None:
    locked = root / "notes" / "locked.txt"
    locked.write_text("nope")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "hello"
        assert first_readable(["locked.txt"]) == ""
    finally:
        locked.chmod(0o600)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""

